CREATE TABLE IF NOT EXISTS settings (id INTEGER PRIMARY KEY CHECK(id=1), academy TEXT NOT NULL, currency TEXT NOT NULL, timezone TEXT NOT NULL, language TEXT NOT NULL);
CREATE TABLE users (id INTEGER PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL UNIQUE, role TEXT NOT NULL CHECK(role IN ('admin','admissions','academic','instructor','finance','manager')), password_hash TEXT NOT NULL);
CREATE TABLE auth_sessions (token TEXT PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id), expires INTEGER NOT NULL);
CREATE TABLE contacts (id INTEGER PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL UNIQUE COLLATE NOCASE, phone TEXT NOT NULL DEFAULT '', language TEXT NOT NULL DEFAULT 'English', consent INTEGER NOT NULL DEFAULT 0, guardian TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL);
CREATE TABLE programs (id INTEGER PRIMARY KEY, name TEXT NOT NULL, category TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', duration TEXT NOT NULL, price INTEGER NOT NULL CHECK(price>=0), currency TEXT NOT NULL, color TEXT NOT NULL DEFAULT 'teal');
CREATE TABLE cohorts (id INTEGER PRIMARY KEY, program_id INTEGER NOT NULL REFERENCES programs(id), name TEXT NOT NULL, instructor_id INTEGER NOT NULL REFERENCES users(id), capacity INTEGER NOT NULL CHECK(capacity>0), start_date TEXT NOT NULL, end_date TEXT NOT NULL, room TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'Active');
CREATE TABLE opportunities (id INTEGER PRIMARY KEY, contact_id INTEGER NOT NULL REFERENCES contacts(id), program_id INTEGER NOT NULL REFERENCES programs(id), owner_id INTEGER NOT NULL REFERENCES users(id), stage TEXT NOT NULL, source TEXT NOT NULL, campaign TEXT NOT NULL DEFAULT '', tags TEXT NOT NULL DEFAULT '', expected_date TEXT NOT NULL DEFAULT '', reason TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, stage_at TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE enrollments (id INTEGER PRIMARY KEY, contact_id INTEGER NOT NULL REFERENCES contacts(id), cohort_id INTEGER NOT NULL REFERENCES cohorts(id), opportunity_id INTEGER UNIQUE REFERENCES opportunities(id), status TEXT NOT NULL DEFAULT 'Active' CHECK(status IN ('Active','Completed','Transferred')), created_at TEXT NOT NULL);
CREATE UNIQUE INDEX one_active_enrollment ON enrollments(contact_id,cohort_id) WHERE status='Active';
CREATE TABLE waitlists (id INTEGER PRIMARY KEY, contact_id INTEGER NOT NULL REFERENCES contacts(id), cohort_id INTEGER NOT NULL REFERENCES cohorts(id), opportunity_id INTEGER REFERENCES opportunities(id), created_at TEXT NOT NULL, UNIQUE(contact_id,cohort_id));
CREATE TABLE sessions (id INTEGER PRIMARY KEY, cohort_id INTEGER NOT NULL REFERENCES cohorts(id), title TEXT NOT NULL, starts_at TEXT NOT NULL, ends_at TEXT NOT NULL, room TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'Scheduled' CHECK(status IN ('Scheduled','Cancelled')));
CREATE TABLE attendance (id INTEGER PRIMARY KEY, session_id INTEGER NOT NULL REFERENCES sessions(id), contact_id INTEGER NOT NULL REFERENCES contacts(id), status TEXT NOT NULL CHECK(status IN ('Present','Absent','Late','Excused')), UNIQUE(session_id,contact_id));
CREATE TABLE tasks (id INTEGER PRIMARY KEY, contact_id INTEGER REFERENCES contacts(id), owner_id INTEGER NOT NULL REFERENCES users(id), title TEXT NOT NULL, due_at TEXT NOT NULL, priority TEXT NOT NULL DEFAULT 'Normal', status TEXT NOT NULL DEFAULT 'Open', created_at TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE charges (id INTEGER PRIMARY KEY, contact_id INTEGER NOT NULL REFERENCES contacts(id), enrollment_id INTEGER REFERENCES enrollments(id), label TEXT NOT NULL, amount INTEGER NOT NULL CHECK(amount>0), discount INTEGER NOT NULL DEFAULT 0 CHECK(discount>=0 AND discount<amount), discount_reason TEXT NOT NULL DEFAULT '', currency TEXT NOT NULL, due_date TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE payments (id INTEGER PRIMARY KEY, charge_id INTEGER NOT NULL REFERENCES charges(id), amount INTEGER NOT NULL CHECK(amount>0), method TEXT NOT NULL, reference TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, user_id INTEGER NOT NULL REFERENCES users(id));
CREATE TABLE refunds (id INTEGER PRIMARY KEY, payment_id INTEGER NOT NULL REFERENCES payments(id), amount INTEGER NOT NULL CHECK(amount>0), reason TEXT NOT NULL, created_at TEXT NOT NULL, user_id INTEGER NOT NULL REFERENCES users(id));
CREATE TABLE activities (id INTEGER PRIMARY KEY, contact_id INTEGER REFERENCES contacts(id), user_id INTEGER NOT NULL REFERENCES users(id), kind TEXT NOT NULL, text TEXT NOT NULL, visibility TEXT NOT NULL DEFAULT 'general', created_at TEXT NOT NULL);
CREATE TABLE documents (id INTEGER PRIMARY KEY, contact_id INTEGER NOT NULL REFERENCES contacts(id), name TEXT NOT NULL, mime TEXT NOT NULL, bytes BLOB NOT NULL, size INTEGER NOT NULL, user_id INTEGER NOT NULL REFERENCES users(id), created_at TEXT NOT NULL);
CREATE TABLE drafts (id INTEGER PRIMARY KEY, contact_id INTEGER NOT NULL REFERENCES contacts(id), channel TEXT NOT NULL, subject TEXT NOT NULL, body TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'Draft', user_id INTEGER NOT NULL REFERENCES users(id), created_at TEXT NOT NULL);
CREATE TABLE automation_runs (id INTEGER PRIMARY KEY, event_key TEXT NOT NULL UNIQUE, rule TEXT NOT NULL, status TEXT NOT NULL, detail TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE flag_resolutions (contact_id INTEGER NOT NULL REFERENCES contacts(id), kind TEXT NOT NULL, fingerprint TEXT NOT NULL, reason TEXT NOT NULL, user_id INTEGER NOT NULL REFERENCES users(id), created_at TEXT NOT NULL, PRIMARY KEY(contact_id,kind));
CREATE TABLE saved_views (id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id), name TEXT NOT NULL, filters TEXT NOT NULL);
CREATE TABLE idempotency (key TEXT NOT NULL, user_id INTEGER NOT NULL REFERENCES users(id), fingerprint TEXT NOT NULL, response TEXT NOT NULL, PRIMARY KEY(key,user_id));
CREATE INDEX opportunities_contact ON opportunities(contact_id);
CREATE INDEX tasks_owner_due ON tasks(owner_id,status,due_at);
CREATE INDEX activities_contact ON activities(contact_id,created_at);
CREATE INDEX sessions_start ON sessions(starts_at);
